using System.Net;using System.Net.Sockets;using System.Text;using System.Text.Json;using System.Threading.Channels;using Spectra;
static byte[] VarBytes(int n){var list=new List<byte>();do{var b=(byte)(n&127);n>>=7;list.Add((byte)(b|(n>0?128:0)));}while(n>0);return list.ToArray();}
static async Task<int> PacketInt(Stream stream){int value=0;for(int n=0;n<5;n++){var b=new byte[1];await stream.ReadExactlyAsync(b);value|=(b[0]&127)<<(7*n);if((b[0]&128)==0)return value;}throw new IOException();}
foreach(var ipv6 in new[]{false,true}){var size=ipv6?56:24;var table=new byte[4+size*2];BitConverter.GetBytes(2u).CopyTo(table,0);var stateOffset=ipv6?48:0;var portOffset=ipv6?20:8;var pidOffset=ipv6?52:20;for(var row=0;row<2;row++){var offset=4+row*size;BitConverter.GetBytes(row==0?2u:5u).CopyTo(table,offset+stateOffset);table[offset+portOffset]=(byte)(25565>>8);table[offset+portOffset+1]=(byte)(25565&255);BitConverter.GetBytes(1234).CopyTo(table,offset+pidOffset);}var ports=LanDiscovery.Parse(table,ipv6).ToArray();if(ports.Length!=1||ports[0]!=(1234,25565))throw new Exception("TCP listener table parsing failed");}
var observer=new ActivityLog();observer.Observe("[12:00:00] [Server thread/INFO]: Starting integrated minecraft server version 1.21.1");observer.Observe("[12:00:01] [Server thread/INFO]: Started serving on 25565");if(observer.State.LanPort!=25565)throw new Exception("Server-thread LAN announcement ignored");observer.Observe("[12:00:02] [Render thread/INFO]: [CHAT] Started serving on 1234");if(observer.State.LanPort!=25565)throw new Exception("Chat spoofed LAN port");Console.WriteLine("PASS: IPv4/IPv6 Java listener discovery and server-thread LAN logs without trusting chat messages");
var statusServer=new TcpListener(IPAddress.Loopback,0);statusServer.Start();var statusPort=((IPEndPoint)statusServer.LocalEndpoint).Port;var responseTask=Task.Run(async()=>{using var client=await statusServer.AcceptTcpClientAsync();var stream=client.GetStream();var handshake=new byte[await PacketInt(stream)];await stream.ReadExactlyAsync(handshake);var request=new byte[2];await stream.ReadExactlyAsync(request);var json=Encoding.UTF8.GetBytes("{\"players\":{\"online\":3},\"favicon\":\"data:image/png;base64,AAAA\"}");var packet=new byte[]{0}.Concat(VarBytes(json.Length)).Concat(json).ToArray();await stream.WriteAsync(VarBytes(packet.Length).Concat(packet).ToArray());});var status=await LanStatus.Query(statusPort);await responseTask;statusServer.Stop();if(status.Players!=3||status.Icon!="data:image/png;base64,AAAA")throw new Exception("Server list ping metadata failed");Console.WriteLine("PASS: Minecraft status protocol returns real player count and icon");
var sourceStore=new Store();var destinationStore=new Store();try{var sourceGame=new GameService();sourceGame.Running["pack-world"]=new();sourceGame.Activities["pack-world"]=new(12345);var root=sourceStore.Folder(new Instance{Id="pack-world"});Directory.CreateDirectory(Path.Combine(root,"mods"));var bytes=Enumerable.Range(0,160000).Select(i=>(byte)(i%251)).ToArray();await File.WriteAllBytesAsync(Path.Combine(root,"mods","test.jar"),bytes);using var hostPacks=new PartyPacks(sourceStore,sourceGame);using var guestPacks=new PartyPacks(destinationStore,new GameService());var manifest=await hostPacks.Share("pack-world");if(manifest.Files.Length!=1)throw new Exception("Manifest missing files");var file=manifest.Files[0];try{PartyPacks.Validate(manifest with{Files=[file with{Name="../escape.jar"}]});throw new Exception("Traversal accepted");}catch(IOException){}var session=guestPacks.Begin(manifest,["mods/test.jar"]);for(long offset=0;offset<file.Size;offset+=65536)await guestPacks.Write(session,file.Hash,offset,await hostPacks.Read("pack-world",file.Hash,offset));var installed=await guestPacks.Commit(session);if(!bytes.SequenceEqual(await File.ReadAllBytesAsync(Path.Combine(destinationStore.Folder(new Instance{Id=installed}),"mods","test.jar"))))throw new Exception("Pack bytes changed");var bad=guestPacks.Begin(manifest,["mods/test.jar"]);for(long offset=0;offset<file.Size;offset+=65536){var block=Convert.FromBase64String(await hostPacks.Read("pack-world",file.Hash,offset));block[0]^=1;await guestPacks.Write(bad,file.Hash,offset,Convert.ToBase64String(block));}try{await guestPacks.Commit(bad);throw new Exception("Bad checksum accepted");}catch(IOException){}guestPacks.Cancel(bad);if(destinationStore.Config.Instances.Count!=1)throw new Exception("Bad download was installed");sourceStore.Config.HideOnlineStatus=true;try{await hostPacks.Read("pack-world",file.Hash,0);throw new Exception("Hidden world shared");}catch(IOException){}Console.WriteLine("PASS: per-world pack chunks, selected files, path validation, SHA-256, separate installation and privacy checks");}finally{if(Directory.Exists(sourceStore.Root))Directory.Delete(sourceStore.Root,true);if(Directory.Exists(destinationStore.Root))Directory.Delete(destinationStore.Root,true);}
var aGame=new GameService();var bGame=new GameService();using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(12));var server=new TcpListener(IPAddress.Loopback,0);server.Start();var serverPort=((IPEndPoint)server.LocalEndpoint).Port;bGame.Running["world"]=new();bGame.Activities["world"]=new(serverPort);var aEvents=Channel.CreateUnbounded<object>();var bEvents=Channel.CreateUnbounded<object>();using var a=new PartyTunnel(aGame,m=>aEvents.Writer.TryWrite(m));using var b=new PartyTunnel(bGame,m=>bEvents.Writer.TryWrite(m));
async Task Route(ChannelReader<object> events,PartyTunnel source,PartyTunnel target,string sourcePeer,string targetPeer){await foreach(var item in events.ReadAllAsync(timeout.Token)){var e=JsonSerializer.SerializeToElement(item);var op=e.GetProperty("operation").GetString();var id=e.GetProperty("id").GetString()!;if(op=="open")await target.Open(targetPeer,id,e.GetProperty("world").GetString()!);else if(op=="data"){await target.Write(targetPeer,id,e.GetProperty("data").GetString()!);source.Ack(sourcePeer,id);}else if(op=="close")target.Close(targetPeer,id);}}
var routeA=Route(aEvents.Reader,a,b,"b","a");var routeB=Route(bEvents.Reader,b,a,"a","b");var echo=Task.Run(async()=>{using var host=await server.AcceptTcpClientAsync(timeout.Token);var buffer=new byte[32768];int count;while((count=await host.GetStream().ReadAsync(buffer,timeout.Token))>0)await host.GetStream().WriteAsync(buffer.AsMemory(0,count),timeout.Token);});
try{try{await b.Open("a",new string('c',32),"not-running");throw new Exception("Unauthorized destination accepted");}catch(IOException){}var port=a.Listen("b","world");if(!a.Owns(port))throw new Exception("Loopback bridge not registered");using var client=new TcpClient();await client.ConnectAsync(IPAddress.Loopback,port,timeout.Token);var payload=Encoding.UTF8.GetBytes(string.Concat(Enumerable.Repeat("Spectra TCP tunnel ✓ ",3000)));await client.GetStream().WriteAsync(payload,timeout.Token);var result=new byte[payload.Length];await client.GetStream().ReadExactlyAsync(result,timeout.Token);if(!payload.SequenceEqual(result))throw new Exception("TCP payload changed");a.DropPeer("b");if(a.Owns(port))throw new Exception("Disconnected listener leaked");Console.WriteLine("PASS: real loopback TCP relay, 60 KB payload with acknowledgements, LAN-only destinations and peer disconnect cleanup");}finally{timeout.Cancel();server.Stop();try{await Task.WhenAll(routeA,routeB,echo);}catch(OperationCanceledException){}catch(IOException){}catch(ObjectDisposedException){}}
